void test_network_fetchlocal__clone_into_mirror ( void ) { git_clone_options opts = GIT_CLONE_OPTIONS_INIT ; git_repository * repo ; git_reference * ref ; opts . bare = true ; opts . remote_cb = remote_mirror_cb ; cl_git_pass ( git_clone ( & repo , cl_git_fixture_url ( "testrepo.git" ) , "./foo.git" , & opts ) ) ; cl_git_pass ( git_reference_lookup ( & ref , repo , "HEAD" ) ) ; cl_assert_equal_i ( GIT_REFERENCE_SYMBOLIC , git_reference_type ( ref ) ) ; cl_assert_equal_s ( "refs/heads/master" , git_reference_symbolic_target ( ref ) ) ; git_reference_free ( ref ) ; cl_git_pass ( git_reference_lookup ( & ref , repo , "refs/remotes/test/master" ) ) ; git_reference_free ( ref ) ; cl_fixture_cleanup ( "./foo.git" ) ; } 